using BenchmarkDotNet.Helpers.Hashing;
using BenchmarkDotNet.Running;
using System.Text;

namespace BenchmarkDotNet.Helpers;

/// <summary>
/// Helper class to generate unique ID for benchmark case.
/// The unique ID is generated by hashing the benchmark case information (e.g. type, method, parameters)
/// </summary>
internal sealed class UniqueIdGenerator
{
    private UniqueIdGenerator() { }

    public static string FromBenchmarkCase(BenchmarkCase benchmarkCase)
    {
        // Note: Assembly's target framework is not included on hash caluculation (Align to MSTest behaviors)
        var hashBytes = new XxHash128()
            .Append(benchmarkCase.Descriptor.Type.Assembly.GetName().Name)
            .Append(benchmarkCase.Descriptor.Type.Namespace)
            .Append(benchmarkCase.Descriptor.DisplayInfo)
            .Append(benchmarkCase.Job.DisplayInfo)
            .Append(benchmarkCase.Parameters.DisplayInfo)
            .GetCurrentHash();

        const int hashVersion = 1; // This version is incremented when hash caluculation algorithm is changed.

        // Create unique guid from first 16 bytes of hash.
        var guid = VersionedGuidFromHash(hashBytes, hashVersion);
        return guid.ToString();
    }

    // This function is based on following testfx implementation.
    // https://github.com/microsoft/testfx/blob/v4.3.2/src/Adapter/MSTestAdapter.PlatformServices/ObjectModel/UnitTestElement.cs#L245
    private static Guid VersionedGuidFromHash(Span<byte> hashBytes, byte hashVersion)
    {
        int firstByte = 0;
        int versionByte = 6;

        // We set first 4 bits to 0001, which is our version. Increase this when we change the hashing algorithm.
        //
        // Note: The logic below is operating on int32, because bitwise operators are not defined for byte in C#. But casting
        // does not affect endianness, so we can safely assume the byte data are at the end of the int.
        // We also don't care to specify the whole expansion of the int in the bit masks, which effectively ignores all the data in the int
        // before the last byte data, but that is okay, they will always be zero.
        hashBytes[firstByte] = (byte)((hashBytes[firstByte] & 0b0000_1111) | (hashVersion << 4));
        // We set first 4bits 7th byte to 8 to indicate that this is a version 8 UUID. https://www.rfc-editor.org/rfc/rfc9562.html#name-uuid-version-8
        hashBytes[versionByte] = (byte)((hashBytes[versionByte] & 0b0000_1111) | 0b1000_0000);

        // We set the first 2 bits of nineth byte to 0b10. In the guid this is stored as byte, so we don't care about endiannes.
        int variantByte = 8;
        hashBytes[variantByte] = (byte)((hashBytes[variantByte] & 0b0011_1111) | 0b1000_0000);

        return CreateGuidFromBigEndian(hashBytes);
    }

    private static Guid CreateGuidFromBigEndian(ReadOnlySpan<byte> bytes)
    {
#if NET9_0_OR_GREATER
        return new Guid(bytes, bigEndian: true);
#else
        return new Guid(
            (bytes[0] << 24) | (bytes[1] << 16) | (bytes[2] << 8) | bytes[3],
            (short)((bytes[4] << 8) | bytes[5]),
            (short)((bytes[6] << 8) | bytes[7]),
            bytes[8], bytes[9], bytes[10], bytes[11], bytes[12], bytes[13], bytes[14], bytes[15]);
#endif
    }
}

file static class Extensions
{
    public static XxHash128 Append(this XxHash128 hasher, string? value)
    {
        if (!string.IsNullOrEmpty(value))
            hasher.Append(Encoding.UTF8.GetBytes(value));
        return hasher;
    }
}